files=[dict(path=str(p.relative_to(O)).replace('\\','/'),bytes=p.stat().st_size,sha256=sha(p.read_bytes())) for p in sorted(O.rglob('*')) if p.is_file() and '__pycache__' not in p.parts and p.name!='output-manifest.json']
